<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Holder\TrustedClientSecretOauthAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientSecretOauthAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TrustedClientSecretOauthAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getSecretOauth returns null on a freshly created holder.
     */
    public function testSecretOauthNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientSecretOauthAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isSecretOauthAssigned());
        $this->assertNull($holder->getSecretOauth());
    }
}
class ImplWithTrustedClientSecretOauthAttributeHolderUnitTest
{
    use TrustedClientSecretOauthAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedSecretOauthRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultSecretOauth();
    }
}
